/**
 * Small chips under the WHATS_CHANGED section only (`DeepDiveSectionCard`'s `deltaChips` param) --
 * the structured form of what that section's prose already narrates in sentence form. Reuses
 * `SignalPill`, the same pill primitive `ConditionChipRow` renders condition chips with on the
 * tactical side -- no new chip component. Neutral-toned throughout: a delta isn't inherently
 * bullish/bearish (a higher P/E isn't a directional read on its own), so this doesn't attempt the
 * BULLISH/BEARISH/NEUTRAL coloring `ConditionChipRow` uses for actual signal chips.
 *
 * Empty `deltas` -> renders nothing (a symbol's first-ever deep dive, or a same-day rerun with no
 * real change, are both normal and expected, not an error state).
 */
@Composable
fun FundamentalsDeltaChips(deltas: List<DomainFundamentalsDelta>, modifier: Modifier = Modifier) {
    if (deltas.isEmpty()) return
    val pulseColors = LocalPulseColors.current

    FlowRow(
        modifier = modifier,
        horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small)),
        verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small))
    ) {
        deltas.forEach { delta ->
            fundamentalsDeltaChipText(delta)?.let { text ->
                SignalPill(text = text, pillColor = pulseColors.signalNeutralPill, contentColor = pulseColors.signalNeutralText)
            }
        }
    }
}

/** "{label}: {from} → {to}", e.g. "Analyst Target: $327 → $328". Null when `field`/`from`/`to` are missing -- a malformed entry is skipped, not rendered blank. `from_date`/`to_date` are deliberately not shown (v1 scope). */
@Composable
private fun fundamentalsDeltaChipText(delta: DomainFundamentalsDelta): String? {
    val field = delta.field ?: return null
    val from = delta.from ?: return null
    val to = delta.to ?: return null

    val meta = deltaFieldMeta[field]
    val label = meta?.let { stringResource(id = it.labelRes) }
        ?: field.replace('_', ' ').replaceFirstChar { it.titlecase(Locale.US) }
    val format = meta?.format ?: DeltaFieldFormat.RATIO

    return "$label: ${formatDeltaValue(from, format)} → ${formatDeltaValue(to, format)}"
}

private enum class DeltaFieldFormat { PERCENT, RATIO, DOLLAR }

