private fun formatDeltaValue(value: Double, format: DeltaFieldFormat): String {
    val decimal = String.format(Locale.US, "%.2f", value)
    return when (format) {
        DeltaFieldFormat.PERCENT -> "$decimal%"
        DeltaFieldFormat.DOLLAR -> "$$decimal"
        DeltaFieldFormat.RATIO -> decimal
    }
}

